window.NOTES={"version":70,"chapters":[{"number":1,"title":"信息技术与计算机文化","summary":"计算机发展、信息表示、硬件、软件与计算机系统的基础概念。","sections":[{"id":"1.1","title":"信息与信息技术"},{"id":"1.2","title":"计算机技术概论"},{"id":"1.3","title":"计算机中信息的表示"},{"id":"1.4","title":"计算机系统"},{"id":"1.5","title":"微型计算机系统"}]},{"number":2,"title":"Windows 10 操作系统","summary":"操作系统特征、Windows界面、文件管理、系统设置与维护。","sections":[{"id":"2.1","title":"操作系统概述"},{"id":"2.2","title":"Windows 10 基础"},{"id":"2.3","title":"文件和文件夹管理"},{"id":"2.4","title":"控制面板"},{"id":"2.5","title":"Windows 10 的系统维护"},{"id":"2.6","title":"Windows 10 的实用工具"}]},{"number":3,"title":"字处理软件 Word 2016","summary":"文档编辑、格式排版、表格、图文混排与长文档功能。","sections":[{"id":"3.1","title":"使用 Office 2016 应用程序"},{"id":"3.2","title":"Word 2016 的基本操作"},{"id":"3.3","title":"文档格式化与排版"},{"id":"3.4","title":"表格制作"},{"id":"3.5","title":"图文混排"},{"id":"3.6","title":"文档的保护与打印"},{"id":"3.7","title":"Word 2016 的高级应用"}]},{"number":4,"title":"电子表格系统 Excel 2016","summary":"工作表操作、公式与函数、格式化、数据处理和图表。","sections":[{"id":"4.1","title":"Excel 2016 概述"},{"id":"4.2","title":"Excel 2016 的基本操作"},{"id":"4.3","title":"Excel 公式与函数"},{"id":"4.4","title":"格式化工作表"},{"id":"4.5","title":"数据处理"},{"id":"4.6","title":"使用图表"}]},{"number":5,"title":"演示文稿软件 PowerPoint 2016","summary":"幻灯片组织、外观、动画、切换与放映设置。","sections":[{"id":"5.1","title":"PowerPoint 2016 基础"},{"id":"5.2","title":"幻灯片页面设计"},{"id":"5.3","title":"幻灯片页面外观的修饰"},{"id":"5.4","title":"动画效果和动作设置"},{"id":"5.5","title":"播放和打印演示文稿"},{"id":"5.6","title":"演示文稿的其他功能"}]},{"number":6,"title":"计算机网络及网页制作","summary":"网络结构、Internet应用、HTML、网页与信息检索。","sections":[{"id":"6.1","title":"计算机网络概述"},{"id":"6.2","title":"计算机网络系统"},{"id":"6.3","title":"Internet 基础和应用"},{"id":"6.4","title":"网页、网页制作及 HTML 简介"},{"id":"6.5","title":"信息检索"}]},{"number":7,"title":"数字多媒体技术基础","summary":"多媒体特征、媒体元素、图像格式、颜色和视频。","sections":[{"id":"7.1","title":"数字多媒体技术概述"},{"id":"7.2","title":"数字多媒体系统组成及常用软件"},{"id":"7.3","title":"常用多媒体制作软件"}]},{"number":8,"title":"信息安全","summary":"安全属性、恶意软件、防火墙、密码技术和信息伦理。","sections":[{"id":"8.1","title":"信息安全概述"},{"id":"8.2","title":"计算机病毒"},{"id":"8.3","title":"防火墙"},{"id":"8.4","title":"Windows 10 操作系统安全"},{"id":"8.5","title":"信息伦理"}]},{"number":9,"title":"信息技术前沿","summary":"虚拟现实、云计算、物联网、区块链与人工智能。","sections":[{"id":"9.1","title":"虚拟现实和增强现实"},{"id":"9.2","title":"云计算和高性能计算"},{"id":"9.3","title":"物联网技术"},{"id":"9.4","title":"大数据技术"},{"id":"9.5","title":"区块链技术"},{"id":"9.6","title":"人工智能"},{"id":"9.7","title":"量子信息"},{"id":"9.8","title":"元宇宙"}]},{"number":10,"title":"数据库技术基础","summary":"关系数据库、数据库管理系统、关系运算、SQL与NoSQL。","sections":[{"id":"10.1","title":"数据库技术基础"},{"id":"10.2","title":"数据库管理系统"},{"id":"10.3","title":"数据库设计与 NoSQL"}]},{"number":11,"title":"计算思维","summary":"计算思维、算法表示、算法特征和基本控制结构。","sections":[{"id":"11.1","title":"计算思维"},{"id":"11.2","title":"计算思维与算法"},{"id":"11.3","title":"算法的控制结构"},{"id":"11.4","title":"面向对象程序设计"},{"id":"11.5","title":"基础算法设计思想"}]}],"notes":[{"q":10,"chapter":5,"section":"5.1","type":"单选","topic":"视图","title":"浏览、普通、备注页和阅读视图的用途","trigger":"题目要求选择便于批量添加、删除和移动幻灯片的视图。","conclusion":"普通视图编辑幻灯片，浏览视图管理整套页面，备注页视图排版说明，阅读视图侧重播放；当前视图决定可操作的对象。","points":["普通视图适合编辑单张幻灯片的文字、图片等对象，下方备注窗格还可输入该页的演讲备注。","幻灯片浏览视图把整套页面显示为缩略图，便于拖动重排、批量选择和设置切换；修改某张幻灯片里的文字应返回普通视图。","阅读视图和放映视图主要用于观看；阅读视图提供翻页控件，幻灯片放映用于向观众演示，不能把二者当作正文编辑区。","备注页视图用于编辑备注并安排打印版式，可调整幻灯片缩略图的位置、大小，或在备注页补充图片；不能在缩略图内部直接改幻灯片正文。删除这里的缩略图只删备注页中的图像，不删除源幻灯片。","演示文稿是保存的一份文件，里面按顺序组织多张幻灯片；每张幻灯片又包含文本、图片、形状、图表、媒体等对象。改整张页面顺序、移动页内图片、修改图片中的文字不是同一操作对象。","PowerPoint、WPS演示等软件都可制作演示文稿。本章操作以Windows桌面版PowerPoint 2016为基线；名称相似的软件或新版功能不保证菜单、快捷键及兼容效果相同。","普通视图左侧缩略图用于选整页，中间编辑区用于选页内对象，下方备注窗格用于写讲稿。功能区随选中对象出现相应工具选项卡；状态栏的缩放只改变屏幕观察比例，不改变幻灯片大小。","“视图→大纲视图”便于梳理标题和正文层级，不等于把页内所有图片、艺术字或自由文本框都转成大纲。“视图→幻灯片母版”编辑共用格式结构；“幻灯片放映”检查观众将看到的顺序、效果与跳转。"],"boundary":"浏览视图擅长结构管理，不适合精细编辑单个对象。","id":"y2020q10","sources":[{"year":2020,"q":10,"type":"单选"},{"year":2022,"q":12,"type":"单选"}],"keys":["2020-10","2022-12"],"related":[{"id":"y2020q12","label":"删除幻灯片要选中缩略图，隐藏不等于删除","reason":"批量删页或隐藏页先在缩略图或浏览视图选中整页，放映画面不代表整页已选中。"},{"id":"y2024q46","label":"默认打开视图在PowerPoint选项中设置","reason":"当前视图按钮只切换本窗口，默认打开视图需另设应用首选项。"},{"id":"y2024q12","label":"从文稿和页面对象进入新建操作","reason":"先认清窗口的对象层级，再创建与选择幻灯片。"}],"pointGroups":[{"title":"先认识对象与窗口","indices":[5,4,6]},{"title":"按编辑与观看任务选择视图","indices":[0,1,7,2]},{"title":"备注页的编辑边界","indices":[3]}],"pointPresentation":{"0":{"title":"按编辑与观看任务选择视图","navigationLabel":"按编辑与观看任务选择视图"},"3":{"title":"备注页的编辑边界","navigationLabel":"备注页的编辑边界"},"4":{"title":"先认清文稿、幻灯片和对象","navigationLabel":"先认清文稿、幻灯片和对象"},"5":{"title":"软件与考试版本","navigationLabel":"软件与考试版本"},"6":{"title":"先找到缩略图、编辑区与备注区","navigationLabel":"先找到缩略图、编辑区与备注区"},"7":{"title":"大纲、母版与放映的任务分工","navigationLabel":"大纲、母版与放映的任务分工"}}},{"q":45,"chapter":5,"section":"5.1","type":"填空","topic":"文件格式","title":"ppsx是PowerPoint放映文件扩展名","trigger":"题目要求填写PowerPoint 2016放映文件的扩展名。","conclusion":".ppsx是PowerPoint放映格式，双击通常直接进入放映；.pptx是普通可编辑演示文稿格式。","points":[".potx是演示文稿模板。",".ppsm和.pptm是可包含宏的格式。","ppsx仍可在PowerPoint中打开并进入编辑界面。","PowerPoint 97—2003常用.ppt演示文稿、.pps放映文件和.pot模板；2016默认普通文稿为.pptx。用“文件→另存为”选择文件类型才执行格式保存，直接改后缀不等于转换。另存旧格式前检查兼容性，SmartArt等结构或效果可能降级。","模板.potx可保存设计、版式及示例内容。先整理可复用页面，再“文件→另存为→PowerPoint模板”；以后“文件→新建→个人/自定义”选择放入个人模板位置的模板（未显示时先核对模板保存位置），新文稿再另存.pptx。模板不是把多个文稿持续同步修改的开关。",".pptm是可含宏的演示文稿，.ppsm是可含宏的放映文件。文件能保存宏与打开时能否执行宏是两回事，实际执行仍受信任中心、安全提示或组织策略控制；扩展名不能代替权限判断。"],"boundary":"放映格式不是不可编辑或加密格式；它主要改变默认打开行为。","id":"y2023q45","sources":[{"year":2023,"q":45,"type":"填空"}],"keys":["2023-45"],"related":[{"id":"merged-4","label":"文件名、扩展名、关联、只读与权限要分层判断","reason":"扩展名影响打开关联，但改后缀不转换内容，也不能提供编辑保护。"},{"id":"y2024q46","label":"默认打开视图在PowerPoint选项中设置","reason":"放映文件的默认双击行为与应用的默认编辑视图是两个层次。"}],"pointPresentation":{"0":{"title":"模板的保存与使用","navigationLabel":"模板的保存与使用"},"1":{"title":"启用宏的文件类型与安全设置","navigationLabel":"启用宏的文件类型与安全设置"},"2":{"title":"区分文稿、放映与旧版保存","navigationLabel":"区分文稿、放映与旧版保存"},"3":{"title":"旧格式与另存为","navigationLabel":"旧格式与另存为"},"4":{"title":"模板用于创建新文稿","navigationLabel":"模板用于创建新文稿","blocks":[{"from":"","label":"用途"},{"from":"先整理","label":"保存"},{"from":"以后","label":"新建与核对"},{"from":"模板不是","label":"影响范围"}]},"5":{"title":"宏格式与宏执行权限","navigationLabel":"宏格式与宏执行权限"}},"pointGroups":[{"title":"区分文稿、放映与旧版保存","indices":[2,3]},{"title":"模板的保存与使用","indices":[0,4]},{"title":"启用宏的文件类型与安全设置","indices":[1,5]}]},{"q":12,"chapter":5,"section":"5.2","type":"单选","topic":"新建幻灯片","title":"Ctrl+M新建幻灯片，Ctrl+N新建演示文稿","trigger":"题目要求辨认PowerPoint中哪些操作能插入新幻灯片。","conclusion":"Ctrl+M在当前演示文稿中插入新幻灯片；Ctrl+N创建新的演示文稿窗口。","points":["“开始→新建幻灯片”可选择版式后插入。","在缩略图窗格右键可选择“新建幻灯片”。","复制幻灯片适合保留现有版式和内容结构。","“文件→新建→空白演示文稿”建立一份文稿；“文件→打开”进入已有文件。首次Ctrl+S需确定位置、名称和类型；继续保存更新当前文件，另存为可保留另一份版本。不能把插入一张新幻灯片当成新建一个文件。","在普通视图左侧或幻灯片浏览视图选择缩略图：单击选一张，Shift选择首尾之间连续页，Ctrl逐张添加或取消不连续页。先把焦点放在缩略图区再Ctrl+A才是选择全部幻灯片；页内编辑区的全选作用于对象或文字。","在缩略图区拖动所选幻灯片到插入线处，改变的是页序，页内内容随整页移动。需要副本时右击缩略图选择“复制幻灯片”，或复制后在目标位置粘贴；副本可独立编辑。移动不增加页数，复制增加页数。","版式规定一页中占位符的类型、位置和格式。选缩略图→“开始→版式”→选“标题和内容”等版式；再向占位符输入内容。应用另一版式后应检查内容映射和位置，手动插入的自由文本框不因此变成版式占位符。","已有页的占位符被手工移动或改格式时，可在“开始→重设”恢复到该页当前版式的安排。重设不是删除全部内容，也不是重建新文稿。若在母版视图修改了版式结构，回到普通视图重新应用相应版式后核对。","要借用另一文稿已有页面，可在“开始→新建幻灯片”下拉菜单进入“重用幻灯片”，选源文件和目标页。留意是否保留源格式：采用目标文稿外观与保留源设计会得到不同结果；插入后核对母版归属和字体。"],"boundary":"新建演示文稿、新建幻灯片和复制幻灯片是三个不同层级的动作。","id":"y2024q12","sources":[{"year":2024,"q":12,"type":"单选"}],"keys":["2024-12"],"related":[{"id":"y2020q10","label":"浏览、普通、备注页和阅读视图的用途","reason":"新建单页后在普通视图编辑，浏览视图则适合管理整套页面顺序。"},{"id":"y2020q11","label":"幻灯片母版、版式与主题形成继承关系","reason":"新建幻灯片要选择版式，占位符和共用外观取决于版式所属母版。"},{"id":"y2020q53","label":"主题、版式与模板的区别","reason":"当前先按版式放内容，统一外观和继承范围在后续辨析。"}],"pointPresentation":{"3":{"title":"先建文件，再打开与保存","navigationLabel":"先建文件，再打开与保存","blocks":[{"from":"","label":"入口与保存"},{"from":"不能把","label":"对象边界"}]},"4":{"title":"选择多张幻灯片","navigationLabel":"选择多张幻灯片","blocks":[{"from":"","label":"选择方法"},{"from":"先把焦点","label":"全选的前提"}]},"5":{"title":"移动与复制整页","navigationLabel":"移动与复制整页","blocks":[{"from":"","label":"移动"},{"from":"需要副本","label":"复制"},{"from":"移动不增加","label":"结果"}]},"6":{"title":"选用版式，再检查占位符","navigationLabel":"选用版式，再检查占位符","blocks":[{"from":"","label":"对象"},{"from":"选缩略图","label":"步骤"},{"from":"应用另一版式","label":"核对与限制"}]},"7":{"title":"重新应用版式与重设","navigationLabel":"重新应用版式与重设"},"8":{"title":"从别的文稿重用页面","navigationLabel":"从别的文稿重用页面"}},"pointGroups":[{"title":"文件与单页的新建层级","indices":[3,0,1]},{"title":"选择、移动与复制整页","indices":[4,5,2]},{"title":"版式、重设与重用","indices":[6,7,8]}]},{"q":12,"chapter":5,"section":"5.2","type":"单选","topic":"幻灯片删除与隐藏","title":"删除幻灯片要选中缩略图，隐藏不等于删除","trigger":"真题从隐藏状态、编辑视图和阅读视图考查整张幻灯片的删除边界。","conclusion":"普通视图缩略图窗格和幻灯片浏览视图可选中整页后删除；隐藏则保留源幻灯片，只让常规顺序放映跳过它。","points":["删除整页会从演示文稿中移除该页；隐藏仍保留内容、对象和已有动画供编辑。","Delete作用于当前选择：选缩略图是删除页面，选页内对象是删除对象，文字光标状态下则编辑文字。","隐藏页在缩略图编号处有隐藏标记；取消隐藏会恢复其参与常规顺序放映的资格。","隐藏页面仍可通过特定链接或放映导航访问；隐藏不等于无法打开。","阅读视图和放映视图主要用于观看，不是常规编辑删除入口。","放映黑屏只是临时遮住观众画面，不会把当前幻灯片设置为隐藏。"],"boundary":"“正在看到一张幻灯片”不等于已选中整页；所有隐藏或删除操作都应跟随当前真实选择，不能固定作用于示例中的某一页。","id":"y2020q12","sources":[{"year":2020,"q":12,"type":"单选"},{"year":2023,"q":12,"type":"单选"}],"keys":["2020-12","2023-12"],"comparison":{"headers":["操作","改变的状态","源页面"],"rows":[["隐藏幻灯片","常规放映跳过","保留"],["删除缩略图","从文件移除整页","移除"],["从自定义放映移除","某方案不再引用该页","保留"],["放映黑屏","临时遮蔽观众画面","保留"]]},"related":[{"id":"y2020q10","label":"浏览、普通、备注页和阅读视图的用途","reason":"删除整张幻灯片前需进入可编辑视图并选中缩略图，避免误删页内对象。"},{"id":"y2026q55","label":"从自定义放映中移除不等于删除幻灯片","reason":"自定义放映移除的是方案引用，隐藏改变常规放映资格，删除才移除源页。"},{"id":"merged-11","label":"幻灯片切换、换片条件、对象动画与动作跳转","reason":"隐藏页仍可通过动作或超链接访问，因此隐藏不等于断开导航入口。"}],"pointGroups":[{"title":"在编辑视图选对对象再删除","indices":[0,1,4]},{"title":"隐藏页面、导航访问与临时黑屏","indices":[2,3,5]}],"pointPresentation":{"0":{"title":"在编辑视图选对对象再删除","navigationLabel":"在编辑视图选对对象再删除"},"2":{"title":"隐藏页面、导航访问与临时黑屏","navigationLabel":"隐藏页面、导航访问与临时黑屏"}}},{"q":13,"chapter":5,"section":"5.2","type":"单选","topic":"节管理与导航","title":"PowerPoint的节用于组织，导航最终定位幻灯片","trigger":"真题从新增、折叠、重命名和放映定位考查PowerPoint节。","conclusion":"节为幻灯片分组，便于编辑和协作；放映时可借助缩略图或节入口导航，但最终显示的仍是具体幻灯片。","points":["点击节名旁的三角可折叠或展开该节，只改变缩略图窗格的显示，不删除其中幻灯片。","节标题本身不是幻灯片。","要在放映时到达某节，最终仍需定位该节中的幻灯片；Windows放映中可输入目标幻灯片编号后按Enter。节名没有独立的放映页码。","点击节标题可选中该节的幻灯片，再设置统一切换效果；只选节内第一页不会自动影响所有页面。“全部应用”则影响整套文稿。","节可包含多张幻灯片，并可整体移动、折叠或展开；同一演示文稿的幻灯片方向通常统一，不能仿照Word给不同节设置不同纸张方向。","在缩略图区选中将成为新节开头的幻灯片，用“开始→节→新增节”，再重命名；调整或删除节时辨明是否同时删除节内幻灯片。节是编辑组织层，复制节内页面并不自动等于复制一个同名节对象。","2024年第13题基于PowerPoint 2010，需分清“转到节”菜单与按幻灯片编号跳转；不能用后者证明该菜单可直达节内任意页。2025年第10题关于“复制节”的参考判断也不能外推到所有版本。本轮未取得相应原生菜单证据，两项保留版本待核；已选幻灯片的复制、节的折叠和移动仍按各自对象判断。"],"boundary":"不能把节、幻灯片和自定义放映混为一谈。","id":"y2025q10","sources":[{"year":2024,"q":13,"type":"单选"},{"year":2025,"q":10,"type":"单选"},{"year":2022,"q":64,"type":"操作"},{"year":2021,"q":26,"type":"多选","page":5}],"keys":["2024-13","2025-10","2022-64","2021-26"],"related":[{"id":"y2026q55","label":"从自定义放映中移除不等于删除幻灯片","reason":"节按编辑结构分组，自定义放映保存播放清单与顺序，二者不能互相替代。"},{"id":"merged-11","label":"幻灯片切换、换片条件、对象动画与动作跳转","reason":"给整节统一切换需先选中该节全部页面，切换效果仍属于每张具体幻灯片。"},{"id":"y2020q61","label":"只改变一页纸张方向","reason":"Word节可分别控制纸张方向，PowerPoint节主要组织页面，跨应用不能照搬能力。"}],"pointGroups":[{"title":"建立节与组织页面","indices":[5,0,1,4]},{"title":"选区范围和放映导航","indices":[3,2,6]}],"pointPresentation":{"0":{"title":"节怎样组织页面与导航","navigationLabel":"节怎样组织页面与导航"},"3":{"title":"选中整节后统一设置切换","navigationLabel":"选中整节后统一设置切换"},"5":{"title":"添加与重命名节","navigationLabel":"添加与重命名节"},"6":{"title":"旧题菜单的版本条件","navigationLabel":"旧题菜单的版本条件"}}},{"q":10,"target":null,"page":3,"chapter":5,"section":"5.2","topic":"空白幻灯片输入","title":"幻灯片文字需要文本框、占位符或形状等载体","conclusion":"空白版式没有现成文本占位符；先插入文本框等对象，再在对象中输入文字。","points":["“插入→文本框”后在幻灯片上单击或拖出区域，即可输入文字。","艺术字、公式、表格和可添加文字的形状也是对象，不是直接把文字写到背景上。","单击背景不等于创建文本插入点；要观察对象边框和闪烁光标。","标题和内容版式含占位符，与空白版式不同。","占位符是版式预先安排的内容容器，既可用于标题、正文，也可按类型承载图片、图表等。普通文本框由使用者在当前页插入；两者都能放文字，但版式重设和自动调整的入口、继承关系不完全相同。","进入对象内部选中文字，再用“开始→字体”修改字号、字体或颜色。设置段落对齐、项目符号、编号、缩进和行距时，先把光标放在目标段落或选中多个段落，再用“开始→段落”。文字居中改变容器内部排版，不会把文本框整体移到幻灯片中央。","“插入→表格”指定行列后，在各单元格输入文字或数据；再用表格工具调整行列、边框与底纹。选中文字、选单元格和选整表的作用范围不同。PowerPoint表格侧重展示，不等于Excel的公式计算工作表。"],"boundary":"不能把网页演示中的输入框误记为PowerPoint背景自带输入区；先有承载对象，再编辑对象文字。","type":"单选","trigger":"围绕空白幻灯片输入的识别、应用与易错边界整理。","id":"y2021q10","sources":[{"year":2021,"q":10,"type":"单选"}],"keys":["2021-10"],"related":[{"id":"y2026q54","label":"占位符文本可自动适应边界","reason":"文本进入占位符后才涉及自动适应边界，普通文本框与占位符的规则仍有差异。"},{"id":"y2020q11","label":"幻灯片母版、版式与主题形成继承关系","reason":"占位符来自所用版式，母版和版式的继承关系解释不同页面为何有不同输入区域。"},{"id":"y2023q35","label":"音频和视频对象的播放范围","reason":"先插入对象，跨页播放、循环与裁剪的具体边界在放映应用中学习。"}],"pointPresentation":{"4":{"title":"占位符与普通文本框","navigationLabel":"占位符与普通文本框"},"5":{"title":"编辑文字与设置段落","navigationLabel":"编辑文字与设置段落","blocks":[{"from":"","label":"选区与格式"},{"from":"设置段落","label":"段落格式"},{"from":"文字居中","label":"层级边界"}]},"6":{"title":"表格用于排列单元格内容","navigationLabel":"表格用于排列单元格内容","blocks":[{"from":"","label":"插入与编辑"},{"from":"选中文字","label":"对象边界"}]}},"pointGroups":[{"title":"先有内容容器，再输入文字","indices":[4,3,0,2]},{"title":"文字、段落与其他内容对象","indices":[5,1,6]}]},{"q":54,"chapter":5,"section":"5.2","type":"操作","topic":"文本自适应","title":"占位符文本可自动适应边界","trigger":"题目要求在不改变占位符大小的情况下容纳更多文字。","conclusion":"要求保持占位符大小时，应让溢出的文字缩小；“调整形状大小以适应文字”扩大的是外框。先确认选中的是正文占位符还是普通文本框，再找对应入口。","points":["正文占位符开始溢出时，左下角出现自动调整菜单，可选“根据占位符自动调整文本”。“调整形状大小以适应文字”在设置形状格式→文本选项→文本框中，它扩大外框，不能满足“不改变占位符大小”的要求。","普通文本框没有占位符左下角的这个菜单，但仍可右击文本框外框→设置形状格式→文本选项→文本框，选择溢出时缩小文字的选项。没有小图标不等于不能自动缩小。","自动缩小按各段文字原有字号的比例缩放，不是把原本不同字号强制设成同一个字号；还可能压缩按比例设置的行距。操作后同时检查文字是否完整、外框是否保持和实际可读性。","文字过多时可精简或拆分幻灯片。正文占位符菜单的“拆分为两张幻灯片”会把已有内容分到两页；“在新幻灯片上继续”保留原页文字，另建一页供继续输入。"],"boundary":"“能放下”不等于“适合演示”，字号过小会降低现场可读性。","id":"y2026q54","sources":[{"year":2026,"q":54,"type":"操作"}],"keys":["2026-54"],"searchAliases":["文字放不下","字超出框","文字溢出","自动缩小字号"],"related":[{"id":"y2021q10","label":"幻灯片文字需要文本框、占位符或形状等载体","reason":"先确认文字位于占位符还是普通文本框，自动调整选项与边界行为可能不同。"},{"id":"y2020q11","label":"幻灯片母版、版式与主题形成继承关系","reason":"占位符结构来自版式，页面异常时应检查所用版式与局部覆盖。"}],"comparison":{"headers":["设置","文字","外框"],"rows":[["不自动调整","可超出边界","保持大小"],["溢出时缩小文字","按需要缩小","保持大小"],["调整形状大小以适应文字","保持字号","增大高度以容纳文字"]]},"pointGroups":null},{"q":53,"chapter":5,"section":"5.2","type":"操作","topic":"替换图片","title":"更改图片可保留对象的大部分效果","trigger":"题目要求替换图片内容，同时尽量保留原对象的动画。","conclusion":"选中图片后使用“更改图片”，通常可以保留其位置、大小、格式和已设置动画。","points":["选中原图片→图片工具→格式→更改图片→选择新图片。直接删除再插入会创建新对象，原动画通常丢失；替换后可在动画窗格核对原对象的效果是否保留。","替换后应检查裁剪比例和清晰度。","选择窗格可帮助确认替换的是正确对象。","“更改图片”替换图片来源；“重设图片”重置图片的格式或裁剪等设置，不负责换成另一张源图片。","“插入→图片”选本地文件后插入，点图片外框再调整大小；要求等比例时在“图片工具→格式”的大小设置中锁定纵横比，再改宽度或高度。图片尺寸与幻灯片尺寸是两个层级。","选图片→“图片工具→格式→裁剪”，拖黑色裁剪柄调整显示范围，完成后点图片外部。缩放改变画面显示大小，裁剪改变看见源图的哪一部分；普通裁剪不等于已永久删除裁掉的数据，压缩图片时删除裁剪区域才会影响恢复。"],"boundary":"不同来源图片比例差异较大时，部分裁剪效果可能需要重新调整。","id":"y2026q53","sources":[{"year":2026,"q":53,"type":"操作"}],"keys":["2026-53"],"related":[{"id":"merged-9","label":"图片尺寸、纵横比与裁剪","reason":"替换图片后纵横比可能不同，需检查裁剪和缩放是否保持主体不变形。"},{"id":"merged-11","label":"幻灯片切换、换片条件、对象动画与动作跳转","reason":"动画附着于页内对象，删除重插会建立新对象，可能失去原有动画设置。"}],"pointGroups":[{"title":"插入、尺寸与裁剪","indices":[4,5]},{"title":"替换同一对象并核对效果","indices":[2,0,3,1]}],"pointPresentation":{"2":{"title":"替换同一对象并核对效果","navigationLabel":"替换同一对象并核对效果"},"4":{"title":"先插入，再调整显示范围","navigationLabel":"先插入，再调整显示范围"},"5":{"title":"裁剪与缩放的区别","navigationLabel":"裁剪与缩放的区别"}}},{"q":26,"chapter":5,"section":"5.2","type":"多选","topic":"艺术字","title":"艺术字是可旋转、填充和组合的图形对象","trigger":"题目判断PowerPoint艺术字的旋转、转换、组合编辑和纹理填充能力。","conclusion":"艺术字可通过旋转手柄任意旋转，可设置文字填充与效果，也可与其他对象组合；组合后仍可进入组内选择单个对象编辑。","points":["选中艺术字外框后拖旋转手柄可旋转整个对象；拖动时按住Shift，以15°为步长约束角度。要求精确角度时，也可在旋转的更多选项中输入数值。","纹理用于文字填充时作用于字形内部，不是对象背景。","普通文本可转换为SmartArt；SmartArt也可转换为形状，但这与把艺术字对象整体直接转换为SmartArt不是同一动作。","单击对象边框，按Shift逐个选中多个对象；被遮挡时用“开始→选择→选择窗格”定位。选好对象后用“绘图工具/图片工具→格式→对齐”，先确认对齐所选对象还是对齐幻灯片。对象对齐移动外框；文本段落对齐只排容器里的文字。","横向或纵向分布用于拉匀多个对象间的间距，不是改文字行距。置于顶层/底层改变前后叠放关系，上移/下移一层只跨过相邻对象；不会改变幻灯片顺序。选择窗格可辅助检查遮挡。","先选中至少两个可组合对象，如艺术字与普通形状，再用“格式→组合→组合”；以后整体移动或旋转，组内成员仍可单独选择。“取消组合”拆开共同操作关系，不删除对象。组合命令不可用时先检查选区和对象类型，不要把所有占位符、表格、媒体都默认视作可组合对象。","2024年第26题基于PowerPoint 2010，配套答案没有选择“不能将艺术字转换为SmartArt”。已核官方说明可证明普通文本/列表转换，但不足以裁决艺术字整体外框与内部文字这两种选择状态。该选项保留待核，不把“艺术字绝不能转”或“所有艺术字必能直接转”当成2016定论。","画形状时，“插入→形状”选图形，再在幻灯片上拖画；需要正方形或正圆时按住Shift拖画。创建艺术字时，“插入→艺术字”选样式，再替换示例文字。选外框调整对象，选内部文字调整字形；形状填充、文字填充不是同一层。","选中具有所需格式的文字或对象→“开始→格式刷”→选中要套用格式的目标；检查目标的字体、颜色等是否按任务改变，目标文字内容仍保持。单击用于一次应用，双击可连续应用，Esc退出；它不替代复制整张幻灯片或复制对象。"],"boundary":"“组合”不等于熔成一张图片；组内对象仍保持独立属性，可通过再次单击或选择窗格定位。","id":"y2024q26","sources":[{"year":2024,"q":26,"type":"多选"}],"keys":["2024-26"],"related":[{"id":"y2022q54","label":"用艺术字创建弯曲、描边和填充的装饰文字","reason":"艺术字的填充、轮廓和转换作用于文字对象，可把Word中的对象格式思路迁移过来。"},{"id":"y2026q36","label":"形状可以与图片、艺术字组合","reason":"组合保留成员的编辑属性，选外框、进入组内与编辑文字应按目标切换。"}],"pointGroups":[{"title":"从创建到选择、对齐与层次","indices":[7,3,4]},{"title":"格式复制、旋转与组合","indices":[8,0,1,5]},{"title":"艺术字与SmartArt的转换边界","indices":[2,6]}],"pointPresentation":{"0":{"title":"旋转、文字填充与组合","navigationLabel":"旋转、文字填充与组合"},"2":{"title":"艺术字与SmartArt的转换边界","navigationLabel":"艺术字与SmartArt的转换边界"},"3":{"title":"对象选择与对齐","navigationLabel":"对象选择与对齐"},"4":{"title":"分布与前后层次","navigationLabel":"分布与前后层次"},"5":{"title":"组合前确认对象，组合后保留成员","navigationLabel":"组合前确认对象，组合后保留成员"},"6":{"title":"艺术字转SmartArt的题目限定","navigationLabel":"艺术字转SmartArt的题目限定"},"7":{"title":"先创建形状或艺术字","navigationLabel":"先创建形状或艺术字","blocks":[{"from":"","label":"形状"},{"from":"创建艺术字","label":"艺术字"},{"from":"选外框","label":"选择层级"}]},"8":{"title":"格式刷复制外观，不复制内容","navigationLabel":"格式刷复制外观，不复制内容","blocks":[{"from":"","label":"操作与结果"},{"from":"单击用于","label":"连续使用"},{"from":"它不替代","label":"边界"}]}}},{"q":64,"chapter":5,"section":"5.2","type":"操作","topic":"SmartArt操作","title":"SmartArt要先辨认选择层级，再改形状、层级或链接","trigger":"真题从更改形状、升降级和给单个节点链接本地文件考查SmartArt对象层级。","conclusion":"先确认选中的是目标形状边框，再按任务使用“更改形状”“升级/降级”或插入超链接；文字光标与整体外框作用范围不同。","points":["降级改变层级，下移只改变同级顺序。","给单个节点链接应选形状边框，再选现有文件或网页。","本地文件链接依赖路径，移动文件后可能失效。","在SmartArt目标节点后新增同级形状，可选中该节点，再用“SmartArt工具→设计→添加形状→在后面添加形状”；在形状内部按Enter通常增加段落，不等同于新增节点。","更改节点为圆角矩形：选中目标形状边框→SmartArt工具→格式→更改形状→圆角矩形。","“插入→SmartArt”选择列表、流程或层次结构等适合任务的布局，再在文本窗格或形状内输入内容。流程强调步骤，层次结构强调上下级；新增节点用SmartArt的添加形状或文本层级操作，不用普通文本换行代替结构变化。","选中目标节点后，在“SmartArt工具→设计”中使用“降级”改变它的层级，使用“下移”调整其顺序。操作后检查文本窗格的缩进与图形连接关系；同样是视觉向下移动，含义可能不同。","给目录中各项分别建立链接且不改变文字样式时，先退出文字编辑，选对应节点的外框，再“插入→超链接→现有文件或网页”指定各自目标。文字选区的链接可能带超链接字符样式，整幅SmartArt外框又不能替各节点分别配置不同目标；建立后在放映中逐项核对。"],"boundary":"选中文字可能只链接文字，选中整体外框可能作用于整个SmartArt；必须观察选择框。","id":"y2025q53","sources":[{"year":2023,"q":64,"type":"操作"},{"year":2023,"q":65,"type":"操作"},{"year":2024,"q":63,"type":"操作"},{"year":2025,"q":53,"type":"操作"},{"year":2021,"q":53,"type":"操作","page":9}],"keys":["2023-64","2023-65","2024-63","2025-53","2021-53"],"related":[{"id":"y2021q10","label":"幻灯片文字需要文本框、占位符或形状等载体","reason":"文字光标、单个对象边框与整体外框的选择层级不同，会决定编辑作用范围。"},{"id":"merged-11","label":"幻灯片切换、换片条件、对象动画与动作跳转","reason":"节点超链接或动作负责目标跳转，页内对象动画不能替代跳转设置。"},{"id":"y2024q26","label":"艺术字是可旋转、填充和组合的图形对象","reason":"SmartArt节点、普通形状和艺术字保留不同编辑能力，转换前先辨认对象类型。"}],"pointGroups":[{"title":"创建图形并辨认结构","indices":[5]},{"title":"调整节点层级、顺序或新增节点","indices":[6,0,3]},{"title":"选中节点后改外形或建立链接","indices":[4,1,7,2]}],"pointPresentation":{"0":{"title":"调整节点层级、顺序或新增节点","navigationLabel":"调整节点层级、顺序或新增节点"},"4":{"title":"选中节点后改外形或建立链接","navigationLabel":"选中节点后改外形或建立链接"},"5":{"title":"先按关系创建SmartArt","navigationLabel":"先按关系创建SmartArt"},"6":{"title":"降级与下移的操作路径","navigationLabel":"降级与下移的操作路径"},"7":{"title":"为什么链接要选节点外框","navigationLabel":"为什么链接要选节点外框"}}},{"q":72,"target":null,"chapter":5,"section":"5.2","topic":"从大纲导入","title":"Word标题层级决定导入PowerPoint后的幻灯片结构","conclusion":"先给Word内容设置标题层级，再在PowerPoint“开始→新建幻灯片→幻灯片（从大纲）”导入。","points":["每个“标题1”建立一张新幻灯片并成为页标题；其后的“标题2”进入这张幻灯片的正文，直到遇见下一个“标题1”。标题和正文归错页时，先修正Word大纲层级。","导入前保存并关闭Word源文件，在PowerPoint选择该文件；常规Windows流程可使用.docx。源文件仍在Word中打开时，应先关闭再导入，不能只切换窗口。","把Word文档作为对象插入，只得到一个对象，不会按标题拆成多张幻灯片。"],"boundary":"只加粗放大不保证建立大纲层级；导入后应检查正文归属和版面。","type":"综合","trigger":"从从大纲导入的判断与应用整理。","id":"y2022q72","sources":[{"year":2022,"q":72,"type":"综合"}],"keys":["2022-72"],"related":[{"id":"merged-5","label":"Word视图、标题结构与导航窗格","reason":"导入前必须先建立Word标题层级，手工加粗放大不会自动形成幻灯片结构。"},{"id":"y2023q52","label":"统一修改同级标题应直接修改样式","reason":"统一应用并修改标题样式，可同时规范Word外观与大纲导入所需的层级。"}],"pointGroups":null},{"q":53,"chapter":5,"section":"5.3","type":"操作","topic":"主题","title":"只给选定幻灯片应用主题","trigger":"题目要求仅改变第一张幻灯片的主题。","conclusion":"先在缩略图窗格选择目标页，再右击主题缩略图并选择“应用于选定幻灯片”，才能明确限定主题的应用范围。","points":["按住Ctrl可选择不相邻幻灯片；应观察缩略图的选中边框，而不是只看中央正在显示哪一页。","直接单击主题通常会影响整套演示文稿；仅选中一页不能代替“应用于选定幻灯片”命令。","主题统一控制颜色、字体和效果，与只更改背景颜色或背景图片不是同一动作。","同一文稿可以使用不同主题，每组主题对应相关母版和版式；添加第二组母版后，已有页面还需使用它的版式才会采用相应设计。","不同主题可满足局部任务要求，但使用过多会降低整套文稿的一致性。","主题是一组协调的颜色、字体和效果；版式安排一页的占位符；正文、图片等是放入页面的具体内容。改主题不是自动改写讲稿，选版式也不是把文件变成模板。","模板是供新建文稿使用的可复用文件，可带设计和示例内容；母版是在当前文稿内管理共用外观的层级，一个母版下可有多个版式。需要未来反复创建类似文稿时保存模板；需要统一当前相关页面的Logo时编辑其母版。"],"boundary":"“重设幻灯片”恢复当前版式相关的占位符位置和格式，不负责更换主题，也不会删除已加入的内容。","version":"已转换为PowerPoint 2016","id":"y2020q53","sources":[{"year":2020,"q":53,"type":"操作"}],"keys":["2020-53"],"comparison":{"headers":["对象","主要负责","不能据此推断"],"rows":[["主题","颜色、字体、效果","不是改写全部正文"],["版式","一页占位符的安排","不等于整份模板文件"],["母版","所辖版式的共用外观","不保证作用于文件内所有母版组"],["模板","用保存的设计/内容新建文稿","不是持续同步多份文稿"],["占位符","版式提供的内容容器","不是所有自由文本框"]]},"related":[{"id":"y2020q11","label":"幻灯片母版、版式与主题形成继承关系","reason":"局部主题会对应相关母版和版式，页面只有使用相应版式才会继承该组设计。"},{"id":"y2020q54","label":"设置背景图片、透明度并应用到全部幻灯片","reason":"主题同时控制颜色、字体和效果，背景图片只改变背景填充，作用范围要分别确认。"}],"pointGroups":[{"title":"主题、模板和版式先分清","indices":[5,6,2]},{"title":"选择页面并限定主题范围","indices":[0,1]},{"title":"多主题与母版归属","indices":[3,4]}],"pointPresentation":{"0":{"title":"选择页面并限定主题范围","navigationLabel":"选择页面并限定主题范围"},"3":{"title":"多主题与母版归属","navigationLabel":"多主题与母版归属"},"5":{"title":"先区分主题、版式和内容","navigationLabel":"先区分主题、版式和内容"},"6":{"title":"模板与母版分别解决什么问题","navigationLabel":"模板与母版分别解决什么问题"}}},{"q":11,"chapter":5,"section":"5.3","type":"单选","topic":"母版与主题","title":"幻灯片母版、版式与主题形成继承关系","trigger":"真题从全篇页脚、母版层级、多个版式和主题替换导致Logo缺失考查PowerPoint继承机制。","conclusion":"普通幻灯片基于所用版式，版式隶属于某组幻灯片母版；统一Logo或固定文字应修改相应母版，作用范围是使用这组母版的页面。","points":["一个母版可关联多个版式，一个演示文稿也可包含多组母版；不能把“本母版下全部页面”理解为文件中的全部页面。","只编辑某个版式影响使用该版式的页面；顶层母版提供其下版式共用的外观，单页或版式上的局部设置可能覆盖继承格式。","母版或版式中的Logo等对象在普通视图不能直接选中修改；要回到“视图→幻灯片母版”并找到实际提供该对象的层级。","修改已有版式的占位符结构后，现有幻灯片可能需要在普通视图重新应用该版式；不能把所有版式变化都理解为立即完整更新。","更换主题可能引入或替换母版；Logo缺失时检查该页实际使用的母版和版式，而不是只检查原先编辑过的母版。","仅让部分页面不显示继承的装饰图形，可启用“隐藏背景图形”；页面仍会放映，本页手动插入的图片不会因此自动隐藏。","PowerPoint区分幻灯片母版、讲义母版和备注母版；普通演示文稿至少有一组幻灯片母版，版式数量并非永远固定。","母版上的普通文本框可以显示固定标识；日期、页脚和编号占位符还需通过“页眉和页脚”启用。","先选有问题的幻灯片并确认所用版式，再“视图→幻灯片母版”，在左侧找到它所属的顶层母版或子版式。加入固定标识后关闭母版视图，核对同组与异组页面；只想改一种布局时应选子版式，不能无差别改顶层。","Logo不见时，依次确认该页实际用哪组母版/哪种版式、标识放在哪一层、是否隐藏背景图形以及有无其他对象遮挡。2025年第60题配套答案使用“主题遮挡”表述，但没有可操作源文稿就不能把它解释成应用主题必定隐藏所有Logo。"],"boundary":"母版管理共用外观，不是逐页正文编辑器；普通视图不能直接改继承的母版对象。固定文本框与自动页脚、日期和编号字段也不能混为一谈。","version":"已转换为PowerPoint 2016","id":"y2020q11","sources":[{"year":2020,"q":11,"type":"单选"},{"year":2023,"q":63,"type":"操作"},{"year":2024,"q":35,"type":"判断"},{"year":2025,"q":60,"type":"分析"},{"year":2021,"q":54,"type":"操作","page":9}],"keys":["2020-11","2023-63","2024-35","2025-60","2021-54"],"comparison":{"headers":["修改位置","影响范围","典型用途"],"rows":[["顶层幻灯片母版","使用该母版的页面","共用Logo、字体和背景"],["某个版式","使用该版式的页面","标题和内容占位符布局"],["普通幻灯片","当前选定页或对象","本页正文、局部格式"]]},"pointGroups":[{"title":"母版、版式与页面的继承范围","indices":[0,1,6]},{"title":"先确定层级，再修改与验证","indices":[8,2,3]},{"title":"主题变化、背景图形与页脚","indices":[4,5,9,7]}],"related":[{"id":"y2020q53","label":"只给选定幻灯片应用主题","reason":"应用另一主题可能改变母版与版式归属，统一Logo缺失时应检查页面实际继承链。"},{"id":"y2024q65","label":"页眉和页脚对话框可隐藏标题页编号","reason":"母版中的编号占位符还需在页眉和页脚对话框启用，存在对象不等于页面显示。"},{"id":"y2020q54","label":"设置背景图片、透明度并应用到全部幻灯片","reason":"隐藏背景图形、背景填充和母版对象是不同层次，不能用更换背景替代所有共用设计。"}],"pointPresentation":{"0":{"title":"母版、版式与页面的继承范围","navigationLabel":"母版、版式与页面的继承范围"},"4":{"title":"主题变化、背景图形与页脚","navigationLabel":"主题变化、背景图形与页脚"},"8":{"title":"实际修改的完整路径","navigationLabel":"实际修改的完整路径"},"9":{"title":"Logo不显示时逐层排查","navigationLabel":"Logo不显示时逐层排查"}}},{"q":54,"chapter":5,"section":"5.3","type":"操作","topic":"背景图片","title":"设置背景图片、透明度并应用到全部幻灯片","trigger":"真题从图片或纹理填充、偏移、透明度和全部应用考查幻灯片背景。","conclusion":"从“设计→设置背景格式”选择图片或纹理填充，调整透明度及相应填充参数；使用“全部应用”可明确把背景推广到整套幻灯片。","points":["背景填充不是普通图片对象，不会出现在选择窗格，也不能像页内图片一样直接选择并拖动。","图片或纹理填充可从图片来源插入图片，也可选择信纸等内置纹理；需要平铺时再设置平铺偏移等参数。","透明度用于调整背景可见程度，修改后应检查正文对比度和可读性。","默认设置作用于当前页；关闭背景窗格会保留当前修改，但不等于已经应用到所有页。","“全部应用”推广到所有页；“重置背景”用于恢复背景格式，不是确认或保存操作。","“设计→幻灯片大小”可选标准、宽屏或自定义大小；自定义中设置幻灯片方向。一份演示文稿的幻灯片大小和方向统一，不能像Word分节那样逐节混用。改变比例后按任务选最大化或确保适合，并逐页检查对象是否超出边界。","幻灯片宽高影响画布；状态栏缩放只改变编辑时的屏幕显示。讲义纸张方向与幻灯片方向可以分别设置；打印预览的纸面安排不能反推源幻灯片已改尺寸。"],"boundary":"插入普通图片并置于底层仍是可选对象，也不会自动覆盖所有幻灯片；更改背景填充并不等于更换完整主题。","version":"已转换为PowerPoint 2016","id":"y2020q54","sources":[{"year":2020,"q":54,"type":"操作"},{"year":2024,"q":64,"type":"操作"},{"year":2022,"q":65,"type":"操作"}],"keys":["2020-54","2024-64","2022-65"],"related":[{"id":"y2020q11","label":"幻灯片母版、版式与主题形成继承关系","reason":"普通视图选不中的内容可能来自母版或背景，两者修改入口和继承范围不同。"},{"id":"y2020q53","label":"只给选定幻灯片应用主题","reason":"更改背景不等于更换主题；局部与全局应用都要按具体命令确认范围。"},{"id":"y2026q53","label":"更改图片可保留对象的大部分效果","reason":"普通图片能更改来源并保留对象效果，背景填充没有可选的页内图片对象。"}],"pointGroups":[{"title":"先确定画布大小与输出层级","indices":[5,6]},{"title":"背景填充与透明度","indices":[0,1,2]},{"title":"当前页、全部应用与重置","indices":[3,4]}],"pointPresentation":{"0":{"title":"背景填充与透明度","navigationLabel":"背景填充与透明度"},"3":{"title":"当前页、全部应用与重置","navigationLabel":"当前页、全部应用与重置"},"5":{"title":"幻灯片大小与方向","navigationLabel":"幻灯片大小与方向"},"6":{"title":"页面大小、屏幕缩放与讲义纸张","navigationLabel":"页面大小、屏幕缩放与讲义纸张"}}},{"q":55,"chapter":5,"section":"5.4","type":"操作","topic":"切换与动作","title":"幻灯片切换、换片条件、对象动画与动作跳转","trigger":"真题从手动/定时换片、动画顺序和鼠标悬停跳转考查PowerPoint动态效果。","conclusion":"切换控制整页之间的过渡，动画控制页内对象，动作或超链接可跳到目标页；效果持续时间、动画开始条件和自动换片时间必须分别设置。","points":["切换属于将要进入的页面：修改第2页到第3页的过渡应选第3页；一页同时只有一个切换效果，重新选择效果会替换原切换。","切换“持续时间”控制过渡本身耗时，数值越大通常越慢；“设置自动换片时间”控制何时前进，不能互换。","“单击鼠标时”与自动换片条件可同时启用；允许单击时，可以在自动换片前主动前进。微软说明自动换片计时在本页最后一个动画或其他效果结束后开始。","动画窗格的前后顺序、开始方式、延迟和持续时间共同决定播放过程；位于第2行不代表一定等第1行结束后才运行。","“单击时”等待放映单击；“与上一动画同时”可与前一效果并行；“上一动画之后”等待前一效果结束。延迟从相应开始条件满足时计算。","一个对象可通过“添加动画”保留已有动画并新增效果；直接从动画库重新选效果可能替换原效果。“预览”只用于查看效果，“持续时间”控制效果本身耗时。","普通“单击时”不要理解为必须点击该对象；指定点击某个对象才播放，需要设置相应动画触发器。","动作设置可分别响应鼠标单击和鼠标悬停；动作、超链接和放映导航可以真正跳到目标幻灯片，包括非相邻页面。","对象动画改变对象的进入、强调、退出或运动方式，不负责指定另一页为跳转目标；应在放映中实际触发并核对目标内容。","切换声音可使用受支持的声音文件；同一节内各页仍可采用不同切换效果。“全部应用”会推广到整套演示文稿。","进入效果让对象出现，强调效果突出已经出现的对象，退出效果让对象离开，动作路径让对象沿指定路径移动。先选页内对象，再“动画→添加动画”选类别；预览后到动画窗格核对是否保留原效果及新效果的顺序。","要求Logo最先出现时，只把Logo的飞入排第一还不够：其他未设置进入动画的可见对象可能在到达本页时就已经显示。应按任务给相关对象设置进入效果，再让Logo先启动，并检查其余对象的开始方式。","选择要进入的幻灯片→“切换”中选效果→查看该效果可用的“效果选项”→分别设置持续时间和换片条件。不是每种切换都有同样的方向或效果选项；要统一所有页才使用“全部应用”。","选中文字或对象→“插入→超链接”，可指向本文档中指定幻灯片、现有文件或网页；需要分别响应单击和鼠标移过时，用“插入→动作”，在对应的鼠标单击/鼠标移过选项中选择“超链接到→幻灯片”，指定目标页后确定。在编辑状态选中对象用于修改，放映时按设定触发跳转；普通视图也可右键打开超链接测试。外部文件链接还要核对目标路径。","动画选项卡的预览用于检查对象效果及配合，切换选项卡的预览用于检查换页效果。2022年第26题基于PowerPoint 2010，关于“只能预览哪类效果”的绝对范围与配套答案仍待该版本核验；不要由按钮名称推导“必定排除另一类效果”。"],"boundary":"定时值越大不等于切换效果越慢；动画窗格顺序不等于全部效果逐个串行；对象动画也不能代替动作或超链接的目标页跳转。","id":"merged-11","sources":[{"year":2020,"q":55,"type":"操作"},{"year":2023,"q":25,"type":"多选"},{"year":2025,"q":54,"type":"操作"},{"year":2025,"q":55,"type":"操作"},{"year":2026,"q":10,"type":"单选"},{"year":2022,"q":26,"type":"多选"},{"year":2021,"q":11,"type":"单选","page":3},{"year":2021,"q":12,"type":"单选","page":3}],"keys":["2020-55","2023-25","2025-54","2025-55","2026-10","2022-26","2021-11","2021-12"],"comparison":{"headers":["设置","作用对象","决定什么"],"rows":[["切换持续时间","进入一页时的过渡","过渡执行多久"],["自动换片时间","当前页的放映过程","何时自动前进"],["动画开始、延迟、持续时间","页内对象效果","何时开始、等待多久、执行多久"],["动作或超链接","可点击或悬停的对象","触发后跳到哪里"]]},"pointGroups":[{"title":"先确定整页还是页内对象","indices":[10,0,12]},{"title":"切换持续时间与换片条件","indices":[1,2,9]},{"title":"对象动画的追加、时序和触发","indices":[5,3,4,6,11]},{"title":"动作、超链接与预览边界","indices":[13,7,8,14]}],"related":[{"id":"y2023q13","label":"排练计时会记录每张幻灯片的放映用时","reason":"排练计时记录每页用时，正式放映采用计时与切换效果持续时间是不同设置。"},{"id":"y2026q55","label":"从自定义放映中移除不等于删除幻灯片","reason":"动作可进入自定义放映并返回主放映，需要先建立正确的页面清单与顺序。"},{"id":"merged-12","label":"保留图表结构才能按系列或类别动画","reason":"图表对象的动画分组取决于是否保留系列和类别结构，图片只能整体播放。"}],"pointPresentation":{"1":{"title":"切换持续时间与换片条件","navigationLabel":"切换持续时间与换片条件"},"5":{"title":"对象动画的追加、时序和触发","navigationLabel":"对象动画的追加、时序和触发"},"10":{"title":"四类动画先按对象状态判断","navigationLabel":"四类动画先按对象状态判断"},"11":{"title":"Logo排第一，还要检查其他对象是否已显示","navigationLabel":"Logo排第一，还要检查其他对象是否已显示"},"12":{"title":"切换的效果选项随效果而变","navigationLabel":"切换的效果选项随效果而变"},"13":{"title":"建立超链接或动作并在放映中核对","navigationLabel":"建立超链接或动作并在放映中核对","blocks":[{"from":"","label":"建立链接"},{"from":"需要分别","label":"动作"},{"from":"在编辑状态","label":"验证与限制"}]},"14":{"title":"预览按钮与旧版本题的限定","navigationLabel":"预览按钮与旧版本题的限定"}}},{"q":64,"chapter":5,"section":"5.4","type":"综合","topic":"图表动画","title":"保留图表结构才能按系列或类别动画","trigger":"两道连续题考查Excel图表粘贴到PowerPoint后如何分部分播放。","conclusion":"要按系列或类别设置图表动画，粘贴时必须保留可编辑的图表结构，再在效果选项中选择分组方式。","points":["粘贴为图片后只能把整张图作为一个对象播放。","可按系列、类别或系列中的元素等方式组织动画。","链接数据便于源表更新，嵌入数据便于文件独立携带。","系列对应图例中的各组数据；类别通常对应横轴标签。“按系列”是一整组依次出现，“按类别”是同一横轴类别下的各系列一起出现。","“插入→图表”选择类型，在随之打开的数据表中填写类别、系列及数值；返回幻灯片检查图例和图形。之后“图表工具→设计→编辑数据”修改数值。截图只保留外观，不保留供编辑数据和分组动画使用的图表结构。"],"boundary":"保留结构与保留源格式不是同一件事；应同时检查粘贴类型和动画分组。","version":"已转换为Office 2016","id":"merged-12","sources":[{"year":2020,"q":64,"type":"综合"},{"year":2020,"q":65,"type":"综合"}],"keys":["2020-64","2020-65"],"related":[{"id":"y2020q59","label":"切换图表的行与列","reason":"按系列或类别播放前，先用图例与横轴确认两者对应的数据维度。"},{"id":"y2022q69","label":"链接Excel表格可随源数据更新，嵌入保留独立副本","reason":"链接决定源数据能否更新，嵌入决定是否带独立副本；它们与保留外观不同。"},{"id":"merged-11","label":"幻灯片切换、换片条件、对象动画与动作跳转","reason":"保留图表结构后还需设置对象动画的开始条件、顺序及持续时间。"}],"pointPresentation":{"3":{"title":"再按系列或类别组织动画","navigationLabel":"再按系列或类别组织动画"},"4":{"title":"插入图表后保留可编辑数据","navigationLabel":"插入图表后保留可编辑数据"}},"pointGroups":[{"title":"先建立与保留图表结构","indices":[4,0,2]},{"title":"再按系列或类别组织动画","indices":[3,1]}]},{"q":13,"chapter":5,"section":"5.5","type":"单选","topic":"排练计时","title":"排练计时会记录每张幻灯片的放映用时","trigger":"题目辨析PowerPoint排练计时的计时显示和保存结果。","conclusion":"排练计时记录当前页用时和累计用时；结束时保留才保存计时，正式放映是否自动前进还取决于是否启用这些时间。","points":["选择“幻灯片放映→排练计时”后开始计时；暂停期间不累计，继续后恢复记录。","换页后当前页计时重新开始，累计时间继续增长；每张幻灯片分别记录自己的用时。","排练结束时可选择保留或丢弃本次记录；保留后可在浏览视图查看各页时长。","保存后仍可在“切换”中修改单页自动换片时间；排练用时与切换效果持续时间不是同一概念。","“设置幻灯片放映”中选择手动可暂时忽略已保存计时；切回使用已有计时才恢复按计时自动前进。","Office 2016录制放映可记录旁白、墨迹和计时；排练计时不能简单等同于录制全部内容，也不要套用新版摄像头录制界面。","在“幻灯片放映”选“从头开始”（F5）或“从当前幻灯片开始”（Shift+F5）；前者从首张常规参与放映的页开始，后者从当前页开始。Esc结束放映回到编辑，不删除文稿或已保存计时。","“幻灯片放映→设置幻灯片放映”中核对放映类型、全部/指定范围/自定义放映，以及手动还是使用已有计时。循环放映与自动推进是不同条件：想无人操作循环播放，还需有可自动前进的计时，并在实际放映中检查最后一页返回开头。","在连接显示设备后检查“幻灯片放映→使用演讲者视图”及监视器设置。演讲者可看当前页、下一页和备注，观众看幻灯片；若画面投反应切换显示器。备注窗格写了内容不等于观众会在普通放映画面看到它。","在本机Windows桌面放映中，可用放映工具栏的笔进行临时标注，结束时按提示选择保留或放弃墨迹；这与编辑正文文字不同。需要查看另一个已打开程序时可用Alt+Tab切换，切换程序不等于删除幻灯片；切回后核对仍处于放映还是编辑状态。"],"boundary":"记录、保存和正式放映采用计时是三个状态；关闭使用计时不等于删除已保存时长，保存排练计时也不会立即开始正式自动放映。","id":"y2023q13","sources":[{"year":2023,"q":13,"type":"单选"},{"year":2021,"q":55,"type":"操作","page":9}],"keys":["2023-13","2021-55"],"comparison":{"headers":["阶段","可见结果"],"rows":[["排练记录","当前页及累计时间增长"],["保留计时","每页时长成为已保存设置"],["正式放映使用计时","按已保存时间自动前进"],["正式放映设为手动","保留时长但暂不自动前进"]]},"related":[{"id":"merged-11","label":"幻灯片切换、换片条件、对象动画与动作跳转","reason":"每页停留用时与过渡效果持续时间不同，自动换片还需核对最后一个动画及换片条件。"},{"id":"y2020q10","label":"浏览、普通、备注页和阅读视图的用途","reason":"保留排练计时后可在浏览视图查看各页时长，再核对页面顺序与整体节奏。"},{"id":"y2023q35","label":"PowerPoint音频可跨幻灯片播放，视频通常停留在所在页","reason":"音频跨页播放与单页视频归属会影响排练节奏，媒体设置需与换片时间一起核对。"}],"pointGroups":[{"title":"先确定如何放映","indices":[6,7,8,9]},{"title":"排练、累计与保存计时","indices":[0,1,2]},{"title":"正式采用计时与录制边界","indices":[3,4,5]}],"pointPresentation":{"0":{"title":"排练、累计与保存计时","navigationLabel":"排练、累计与保存计时"},"3":{"title":"正式采用计时与录制边界","navigationLabel":"正式采用计时与录制边界"},"6":{"title":"从头、从当前页与结束放映","navigationLabel":"从头、从当前页与结束放映"},"7":{"title":"先设置放映范围和推进方式","navigationLabel":"先设置放映范围和推进方式"},"8":{"title":"演讲者视图与观众画面","navigationLabel":"演讲者视图与观众画面"},"9":{"title":"放映标注与切换程序","navigationLabel":"放映标注与切换程序","blocks":[{"from":"","label":"标注与墨迹"},{"from":"需要查看","label":"切换程序"}]}}},{"q":55,"chapter":5,"section":"5.5","type":"操作","topic":"自定义放映","title":"从自定义放映中移除不等于删除幻灯片","trigger":"题目要求在自定义放映列表中取消某张幻灯片。","conclusion":"进入“自定义幻灯片放映”，编辑目标方案并从右侧清单移除目标页；这只改变方案中的引用，原幻灯片仍保留。","points":["自定义放映在当前文件中保存所需页面的引用及播放顺序，不是另存一份演示文稿。","左侧是演示文稿中的源幻灯片，选中后可添加到右侧“自定义放映中的幻灯片”清单。","右侧上移或下移只调整该方案的播放顺序，不改变普通视图中的真实页序。","从右侧清单移除只影响当前方案；源页仍能编辑，也能用于其他方案。","一个文件可建立多个自定义放映方案；编辑完成后选择正确方案并实际放映，核对页序和内容。","通过动作或超链接进入自定义放映时，可根据任务设置“放映并返回”，使辅助放映结束后返回主放映。"],"boundary":"从清单移除、删除整个方案和在普通视图删除源幻灯片是不同操作；取消编辑应保留此前已保存的方案。","id":"y2026q55","sources":[{"year":2026,"q":55,"type":"操作"},{"year":2022,"q":74,"type":"综合"}],"keys":["2026-55","2022-74"],"related":[{"id":"y2020q12","label":"删除幻灯片要选中缩略图，隐藏不等于删除","reason":"移除方案引用、隐藏源页与删除源页分别改变不同对象，要按清单和缩略图位置判断。"},{"id":"y2025q10","label":"PowerPoint的节用于组织，导航最终定位幻灯片","reason":"节组织编辑结构，自定义放映组织播放路径，调整方案顺序不会重排普通视图的真实页序。"},{"id":"merged-11","label":"幻灯片切换、换片条件、对象动画与动作跳转","reason":"通过动作或超链接进入辅助放映时，可设置放映并返回，核对真正的跳转目标。"}],"pointGroups":[{"title":"编辑方案引用与独立播放顺序","indices":[0,1,2,3]},{"title":"核对多个方案与放映并返回","indices":[4,5]}],"pointPresentation":{"0":{"title":"编辑方案引用与独立播放顺序","navigationLabel":"编辑方案引用与独立播放顺序"},"4":{"title":"核对多个方案与放映并返回","navigationLabel":"核对多个方案与放映并返回"}}},{"q":35,"chapter":5,"section":"5.5","type":"判断","topic":"音视频播放","title":"PowerPoint音频可跨幻灯片播放，视频通常停留在所在页","trigger":"题目判断插入的视频是否既能裁剪又能跨多张幻灯片连续播放。","conclusion":"PowerPoint2016可裁剪本地插入的音频和视频；音频可跨幻灯片播放，普通嵌入视频通常在离开其所在幻灯片时停止。","points":["“在后台播放”会为音频组合跨幻灯片、循环等常用设置。","视频播放选项可控制自动/单击开始、全屏和循环。","裁剪只改变媒体使用的起止时间，不改变页面归属。选中本地插入的视频后，用视频工具→播放→裁剪视频设置起止点；在线插入的视频不支持PowerPoint的这套裁剪功能，应先确认媒体来源。","PowerPoint 2016可在“音频工具→播放”选择跨幻灯片播放，并按需启用“循环播放，直到停止”；“播完返回开头”不是循环播放。","在“插入→音频/视频”选择本机文件，插入后选媒体对象，才会出现相应播放工具。嵌入内容便于随文稿携带，链接文件或网络媒体则依赖可访问的来源；跨计算机交付前应实际检查媒体能否播放。"],"boundary":"不要把音频的“跨幻灯片播放”选项套到视频；若需跨页视觉连续，应重新设计媒体或放映结构。","id":"y2023q35","sources":[{"year":2023,"q":35,"type":"判断"},{"year":2022,"q":63,"type":"操作"}],"keys":["2023-35","2022-63"],"related":[{"id":"merged-11","label":"幻灯片切换、换片条件、对象动画与动作跳转","reason":"媒体开始方式与页面自动换片条件共同影响播放过程，不能把切换时间当作媒体时长。"},{"id":"y2023q13","label":"排练计时会记录每张幻灯片的放映用时","reason":"用排练计时核对讲解和媒体节奏，但记录时长不等于录制全部旁白与内容。"}],"pointGroups":[{"title":"先插入，再设开始与播放范围","indices":[4,0,1]},{"title":"裁剪、跨页、循环与返回开头","indices":[2,3]}],"pointPresentation":{"2":{"title":"裁剪、跨页、循环与返回开头","navigationLabel":"裁剪、跨页、循环与返回开头"},"4":{"title":"插入媒体前确认来源","navigationLabel":"插入媒体前确认来源"}}},{"q":65,"chapter":5,"section":"5.5","type":"操作","topic":"幻灯片编号","title":"页眉和页脚对话框可隐藏标题页编号","trigger":"题目要求给所有幻灯片编号，但不在标题幻灯片显示。","conclusion":"打开“插入→幻灯片编号”，勾选“幻灯片编号”和“标题幻灯片中不显示”，再单击“全部应用”；编号位置与样式由母版或版式控制。","points":["“应用”作用于当前选定幻灯片，“全部应用”作用于整个演示文稿。","编号占位符的位置和样式由版式或母版控制；母版中存在占位符，不等于已经在页面上启用编号。","标题幻灯片的识别与所用版式有关，不能机械地理解为永远只排除文件第1页。","“插入→日期和时间/页眉和页脚”中勾选日期和时间并选择“自动更新”，再“全部应用”，可加入日期字段；手输日期只是固定文字。","自动日期在打开或打印演示文稿时反映当前日期；固定日期保持输入的文字。","页脚文字须在“页眉和页脚”中勾选并填写；母版普通文本框中的固定标识不是同一类页脚字段。"],"boundary":"隐藏编号不会删除该幻灯片，也不会改变后续幻灯片的实际编号序列；直接在文本框输入“1”不会成为自动编号。","id":"y2024q65","sources":[{"year":2024,"q":65,"type":"操作"},{"year":2022,"q":73,"type":"综合"}],"keys":["2024-65","2022-73"],"related":[{"id":"y2020q11","label":"幻灯片母版、版式与主题形成继承关系","reason":"编号与页脚的位置来自母版或版式，是否显示仍需在页眉和页脚中启用。"},{"id":"y2020q12","label":"删除幻灯片要选中缩略图，隐藏不等于删除","reason":"标题页不显示编号只改编号外观，隐藏页面改变常规放映资格，两者都不同于删页。"},{"id":"y2024q55","label":"在形状中放置光标后插入PAGE域","reason":"Word页码与PowerPoint编号都应使用动态字段，手输数字不会自动跟随页面变化。"}],"pointGroups":[{"title":"编号启用、母版位置与标题页例外","indices":[0,1,2]},{"title":"自动日期、固定日期与页脚文字","indices":[3,4,5]}],"pointPresentation":{"0":{"title":"编号启用、母版位置与标题页例外","navigationLabel":"编号启用、母版位置与标题页例外"},"3":{"title":"自动日期、固定日期与页脚文字","navigationLabel":"自动日期、固定日期与页脚文字"}}},{"id":"syllabus-ppt-output","chapter":5,"section":"5.5","origin":"syllabus","topic":"考纲补充","title":"PPT先按交付目标选择打印、共享或导出","conclusion":"需要继续编辑时保留PPTX；PPSX通常以放映方式打开；固定页面阅读可导出PDF；需要连续播放的成片可导出视频。扩展名与具体保存/导出操作配合决定交付用途。","points":["文件→打印中，整页幻灯片便于逐页检查画面；讲义可在一张纸上放多张幻灯片；备注页包含当前幻灯片和演讲者备注；大纲侧重文本结构。","共享前核对目标：发送附件形成副本；共享云端链接仍指向同一文件，并需确认查看或编辑权限。导出后检查页数、字体、图片和超链接等关键结果。","视频导出需检查旁白、动画和幻灯片计时；PDF不会按放映方式执行全部动画和切换。","“文件→打印”中选打印机，再选全部、当前、选定或自定义范围。自定义如1,3,5-7表示这些幻灯片，不是讲义的第几张纸；有隐藏页时另核对是否打印隐藏幻灯片。最后看预览、份数和彩色/灰度等设置，再执行打印。","讲义可按每页1、2、3、4、6、9张等布局排版，3张讲义还带笔记线。例：7张幻灯片按每页3张输出，需要3张纸面，最后一面只排1张；这不会把源文稿减少为3张幻灯片。打印份数和双面方式还会影响实际用纸。","备注页通常把一张幻灯片和该页演讲者备注放在一页；大纲以标题、正文层级为主，不是完整画面；讲义的笔记线供读者书写，不等于自动印出讲稿。先确认需要画面还是备注，再选输出内容。","“视图→讲义母版”设置讲义方向、页眉页脚、日期和纸面页码等共用外观；幻灯片母版控制源幻灯片。讲义页码数的是纸面，幻灯片编号数的是文稿页面；不能混作同一个计数对象。","需要固定画面时，“文件→导出→创建PDF/XPS”并在选项中核对范围及发布内容；需要连续播放成片时选“创建视频”，确认是否使用录制的计时和旁白。两者都应保留.pptx供以后编辑，导出后重新打开检查结果。","2016桌面共享云端文件通常需要OneDrive或SharePoint位置及相应账户权限；分享链接指向同一文件，发送附件则给出独立副本。需连同外部链接资源移交时可检查“文件→导出→将演示文稿打包成CD”，也可复制到文件夹；打包不是视频转换，也不能保证目标机拥有所有字体和媒体支持。"],"boundary":"交付文件能打开不等于所有动态效果都已保留；应按目标格式核对。","sources":[],"trigger":"依据山东省2026年专升本公共基础课考试要求补充；下方为教学示例。","related":[{"id":"y2023q45","label":"ppsx是PowerPoint放映文件扩展名","reason":"联系相邻知识理解作用范围"},{"id":"y2024q46","label":"应用级选项与当前页视图","reason":"文件交付与应用默认选项分别在5.5和5.6查询。"}],"pointPresentation":{"1":{"title":"共享与导出后核对","navigationLabel":"共享与导出后核对"},"3":{"title":"先选打印范围，再选纸面布局","navigationLabel":"先选打印范围，再选纸面布局","blocks":[{"from":"","label":"范围"},{"from":"自定义如","label":"编号含义"},{"from":"最后看","label":"预览后输出"}]},"4":{"title":"讲义每页张数与纸张页数","navigationLabel":"讲义每页张数与纸张页数"},"5":{"title":"备注、大纲与讲义中的文字","navigationLabel":"备注、大纲与讲义中的文字"},"6":{"title":"讲义母版与幻灯片母版","navigationLabel":"讲义母版与幻灯片母版"},"7":{"title":"导出PDF或视频后再核对","navigationLabel":"导出PDF或视频后再核对","blocks":[{"from":"","label":"固定画面"},{"from":"需要连续","label":"播放成片"},{"from":"两者都应","label":"交付核对"}]},"8":{"title":"共享、附件与打包的交付边界","navigationLabel":"共享、附件与打包的交付边界","blocks":[{"from":"","label":"共享与附件"},{"from":"需连同","label":"打包"},{"from":"打包不是","label":"限制"}]}},"pointGroups":[{"title":"确定范围与输出内容","indices":[3,0,5]},{"title":"讲义布局、纸面与母版","indices":[4,6]},{"title":"共享与导出后核对","indices":[1,7,2,8]}]},{"q":46,"chapter":5,"section":"5.6","type":"填空","topic":"PowerPoint选项","title":"默认打开视图在PowerPoint选项中设置","trigger":"题目要求把演示文稿打开时的默认视图设置为幻灯片浏览视图。","conclusion":"PowerPoint2016在文件→选项→高级→显示的“使用此视图打开所有文档”列表中设置默认打开视图，选择后单击“确定”。","points":["这是应用级首选项，不是当前幻灯片上的对象。","状态栏视图按钮只切换当前窗口视图。","设置后单击“确定”，再打开文档验证指定视图；若只是暂时切到浏览视图，不会改写这个应用级默认选项。"],"boundary":"把文件保存时停在浏览视图不等于设置所有文档的默认打开视图。","id":"y2024q46","sources":[{"year":2024,"q":46,"type":"填空"}],"keys":["2024-46"],"related":[{"id":"y2020q10","label":"浏览、普通、备注页和阅读视图的用途","reason":"先按编辑单页、管理顺序或观看放映的用途选择合适默认视图。"},{"id":"y2023q45","label":"ppsx是PowerPoint放映文件扩展名","reason":"ppsx双击进入放映属于文件打开行为，不应与普通文稿的视图首选项混淆。"}],"pointGroups":null}],"sourceCount":460,"years":[2020,2021,2022,2023,2024,2025,2026]};
