window.NOTE_DEMOS={"y2020q10":{"kind":"explore","title":"选择PowerPoint视图","task":"点击任务，观察最适合的工作区。","initial":"视图选择取决于要编辑单页还是调整整体顺序。","actions":[{"label":"快速重排多张幻灯片","stage":"幻灯片浏览视图","result":"缩略图铺开，便于移动、复制、删除和设置切换。","tone":"good"},{"label":"精细编辑当前页","stage":"普通视图","result":"包含缩略图窗格、编辑区和备注区。","tone":"good"},{"label":"观看最终播放效果","stage":"幻灯片放映视图","result":"以全屏方式播放。","tone":"good"}]},"y2023q45":{"kind":"explore","title":"双击四种PowerPoint文件看默认行为","task":"选择扩展名，观察它是编辑文稿、放映、模板还是宏文件。","initial":"扩展名主要决定文件类型和默认打开方式。","actions":[{"label":".pptx","stage":"普通演示文稿","result":"双击通常进入编辑界面。","tone":"good"},{"label":".ppsx","stage":"PowerPoint放映","result":"双击通常直接开始放映，仍可用PowerPoint编辑。","tone":"good"},{"label":".potx","stage":"演示文稿模板","result":"用于创建采用该设计的新文件。","tone":"good"},{"label":".ppsm","stage":"启用宏的放映","result":"可包含VBA宏，打开时要注意安全来源。","tone":"warn"}]}};
window.NOTE_NAVIGATION={"y2020q10":{"related":[{"id":"y2020q12","label":"删除幻灯片要选中缩略图，隐藏不等于删除","reason":"批量删页或隐藏页先在缩略图或浏览视图选中整页，放映画面不代表整页已选中。","chapter":5},{"id":"y2024q46","label":"默认打开视图在PowerPoint选项中设置","reason":"当前视图按钮只切换本窗口，默认打开视图需另设应用首选项。","chapter":5},{"id":"y2024q12","label":"从文稿和页面对象进入新建操作","reason":"先认清窗口的对象层级，再创建与选择幻灯片。","chapter":5}],"topics":[]},"y2023q45":{"related":[{"id":"merged-4","label":"文件名、扩展名、关联、只读与权限要分层判断","reason":"扩展名影响打开关联，但改后缀不转换内容，也不能提供编辑保护。","chapter":2},{"id":"y2024q46","label":"默认打开视图在PowerPoint选项中设置","reason":"放映文件的默认双击行为与应用的默认编辑视图是两个层次。","chapter":5}],"topics":[]},"y2024q12":{"related":[{"id":"y2020q10","label":"浏览、普通、备注页和阅读视图的用途","reason":"新建单页后在普通视图编辑，浏览视图则适合管理整套页面顺序。","chapter":5},{"id":"y2020q11","label":"幻灯片母版、版式与主题形成继承关系","reason":"新建幻灯片要选择版式，占位符和共用外观取决于版式所属母版。","chapter":5},{"id":"y2020q53","label":"主题、版式与模板的区别","reason":"当前先按版式放内容，统一外观和继承范围在后续辨析。","chapter":5}],"topics":[]},"y2020q12":{"related":[{"id":"y2020q10","label":"浏览、普通、备注页和阅读视图的用途","reason":"删除整张幻灯片前需进入可编辑视图并选中缩略图，避免误删页内对象。","chapter":5},{"id":"y2026q55","label":"从自定义放映中移除不等于删除幻灯片","reason":"自定义放映移除的是方案引用，隐藏改变常规放映资格，删除才移除源页。","chapter":5},{"id":"merged-11","label":"幻灯片切换、换片条件、对象动画与动作跳转","reason":"隐藏页仍可通过动作或超链接访问，因此隐藏不等于断开导航入口。","chapter":5}],"topics":[{"id":"cmp-visible-and-removed","title":"不见了：清除、隐藏、筛选还是移除？"},{"id":"cmp-delete-context","title":"同一个Delete，作用对象可能完全不同"}]},"y2025q10":{"related":[{"id":"y2026q55","label":"从自定义放映中移除不等于删除幻灯片","reason":"节按编辑结构分组，自定义放映保存播放清单与顺序，二者不能互相替代。","chapter":5},{"id":"merged-11","label":"幻灯片切换、换片条件、对象动画与动作跳转","reason":"给整节统一切换需先选中该节全部页面，切换效果仍属于每张具体幻灯片。","chapter":5},{"id":"y2020q61","label":"只改变一页纸张方向","reason":"Word节可分别控制纸张方向，PowerPoint节主要组织页面，跨应用不能照搬能力。","chapter":3}],"topics":[{"id":"cmp-ppt-object-slide-deck","title":"PowerPoint：对象、页面、节、母版与全稿"}]},"y2021q10":{"related":[{"id":"y2026q54","label":"占位符文本可自动适应边界","reason":"文本进入占位符后才涉及自动适应边界，普通文本框与占位符的规则仍有差异。","chapter":5},{"id":"y2020q11","label":"幻灯片母版、版式与主题形成继承关系","reason":"占位符来自所用版式，母版和版式的继承关系解释不同页面为何有不同输入区域。","chapter":5},{"id":"y2023q35","label":"音频和视频对象的播放范围","reason":"先插入对象，跨页播放、循环与裁剪的具体边界在放映应用中学习。","chapter":5}],"topics":[]},"y2026q54":{"related":[{"id":"y2021q10","label":"幻灯片文字需要文本框、占位符或形状等载体","reason":"先确认文字位于占位符还是普通文本框，自动调整选项与边界行为可能不同。","chapter":5},{"id":"y2020q11","label":"幻灯片母版、版式与主题形成继承关系","reason":"占位符结构来自版式，页面异常时应检查所用版式与局部覆盖。","chapter":5}],"topics":[]},"y2026q53":{"related":[{"id":"merged-9","label":"图片尺寸、纵横比与裁剪","reason":"替换图片后纵横比可能不同，需检查裁剪和缩放是否保持主体不变形。","chapter":3},{"id":"merged-11","label":"幻灯片切换、换片条件、对象动画与动作跳转","reason":"动画附着于页内对象，删除重插会建立新对象，可能失去原有动画设置。","chapter":5}],"topics":[]},"y2024q26":{"related":[{"id":"y2022q54","label":"用艺术字创建弯曲、描边和填充的装饰文字","reason":"艺术字的填充、轮廓和转换作用于文字对象，可把Word中的对象格式思路迁移过来。","chapter":3},{"id":"y2026q36","label":"形状可以与图片、艺术字组合","reason":"组合保留成员的编辑属性，选外框、进入组内与编辑文字应按目标切换。","chapter":3}],"topics":[]},"y2025q53":{"related":[{"id":"y2021q10","label":"幻灯片文字需要文本框、占位符或形状等载体","reason":"文字光标、单个对象边框与整体外框的选择层级不同，会决定编辑作用范围。","chapter":5},{"id":"merged-11","label":"幻灯片切换、换片条件、对象动画与动作跳转","reason":"节点超链接或动作负责目标跳转，页内对象动画不能替代跳转设置。","chapter":5},{"id":"y2024q26","label":"艺术字是可旋转、填充和组合的图形对象","reason":"SmartArt节点、普通形状和艺术字保留不同编辑能力，转换前先辨认对象类型。","chapter":5}],"topics":[{"id":"cmp-ppt-object-slide-deck","title":"PowerPoint：对象、页面、节、母版与全稿"}]},"y2022q72":{"related":[{"id":"merged-5","label":"Word视图、标题结构与导航窗格","reason":"导入前必须先建立Word标题层级，手工加粗放大不会自动形成幻灯片结构。","chapter":3},{"id":"y2023q52","label":"统一修改同级标题应直接修改样式","reason":"统一应用并修改标题样式，可同时规范Word外观与大纲导入所需的层级。","chapter":3}],"topics":[]},"y2020q53":{"related":[{"id":"y2020q11","label":"幻灯片母版、版式与主题形成继承关系","reason":"局部主题会对应相关母版和版式，页面只有使用相应版式才会继承该组设计。","chapter":5},{"id":"y2020q54","label":"设置背景图片、透明度并应用到全部幻灯片","reason":"主题同时控制颜色、字体和效果，背景图片只改变背景填充，作用范围要分别确认。","chapter":5}],"topics":[{"id":"cmp-ppt-object-slide-deck","title":"PowerPoint：对象、页面、节、母版与全稿"}]},"y2020q11":{"related":[{"id":"y2020q53","label":"只给选定幻灯片应用主题","reason":"应用另一主题可能改变母版与版式归属，统一Logo缺失时应检查页面实际继承链。","chapter":5},{"id":"y2024q65","label":"页眉和页脚对话框可隐藏标题页编号","reason":"母版中的编号占位符还需在页眉和页脚对话框启用，存在对象不等于页面显示。","chapter":5},{"id":"y2020q54","label":"设置背景图片、透明度并应用到全部幻灯片","reason":"隐藏背景图形、背景填充和母版对象是不同层次，不能用更换背景替代所有共用设计。","chapter":5}],"topics":[{"id":"cmp-ppt-object-slide-deck","title":"PowerPoint：对象、页面、节、母版与全稿"}]},"y2020q54":{"related":[{"id":"y2020q11","label":"幻灯片母版、版式与主题形成继承关系","reason":"普通视图选不中的内容可能来自母版或背景，两者修改入口和继承范围不同。","chapter":5},{"id":"y2020q53","label":"只给选定幻灯片应用主题","reason":"更改背景不等于更换主题；局部与全局应用都要按具体命令确认范围。","chapter":5},{"id":"y2026q53","label":"更改图片可保留对象的大部分效果","reason":"普通图片能更改来源并保留对象效果，背景填充没有可选的页内图片对象。","chapter":5}],"topics":[{"id":"cmp-ppt-object-slide-deck","title":"PowerPoint：对象、页面、节、母版与全稿"}]},"merged-11":{"related":[{"id":"y2023q13","label":"排练计时会记录每张幻灯片的放映用时","reason":"排练计时记录每页用时，正式放映采用计时与切换效果持续时间是不同设置。","chapter":5},{"id":"y2026q55","label":"从自定义放映中移除不等于删除幻灯片","reason":"动作可进入自定义放映并返回主放映，需要先建立正确的页面清单与顺序。","chapter":5},{"id":"merged-12","label":"保留图表结构才能按系列或类别动画","reason":"图表对象的动画分组取决于是否保留系列和类别结构，图片只能整体播放。","chapter":5}],"topics":[{"id":"cmp-ppt-object-slide-deck","title":"PowerPoint：对象、页面、节、母版与全稿"}]},"merged-12":{"related":[{"id":"y2020q59","label":"切换图表的行与列","reason":"按系列或类别播放前，先用图例与横轴确认两者对应的数据维度。","chapter":4},{"id":"y2022q69","label":"链接Excel表格可随源数据更新，嵌入保留独立副本","reason":"链接决定源数据能否更新，嵌入决定是否带独立副本；它们与保留外观不同。","chapter":3},{"id":"merged-11","label":"幻灯片切换、换片条件、对象动画与动作跳转","reason":"保留图表结构后还需设置对象动画的开始条件、顺序及持续时间。","chapter":5}],"topics":[]},"y2023q13":{"related":[{"id":"merged-11","label":"幻灯片切换、换片条件、对象动画与动作跳转","reason":"每页停留用时与过渡效果持续时间不同，自动换片还需核对最后一个动画及换片条件。","chapter":5},{"id":"y2020q10","label":"浏览、普通、备注页和阅读视图的用途","reason":"保留排练计时后可在浏览视图查看各页时长，再核对页面顺序与整体节奏。","chapter":5},{"id":"y2023q35","label":"PowerPoint音频可跨幻灯片播放，视频通常停留在所在页","reason":"音频跨页播放与单页视频归属会影响排练节奏，媒体设置需与换片时间一起核对。","chapter":5}],"topics":[]},"y2026q55":{"related":[{"id":"y2020q12","label":"删除幻灯片要选中缩略图，隐藏不等于删除","reason":"移除方案引用、隐藏源页与删除源页分别改变不同对象，要按清单和缩略图位置判断。","chapter":5},{"id":"y2025q10","label":"PowerPoint的节用于组织，导航最终定位幻灯片","reason":"节组织编辑结构，自定义放映组织播放路径，调整方案顺序不会重排普通视图的真实页序。","chapter":5},{"id":"merged-11","label":"幻灯片切换、换片条件、对象动画与动作跳转","reason":"通过动作或超链接进入辅助放映时，可设置放映并返回，核对真正的跳转目标。","chapter":5}],"topics":[{"id":"cmp-visible-and-removed","title":"不见了：清除、隐藏、筛选还是移除？"}]},"y2023q35":{"related":[{"id":"merged-11","label":"幻灯片切换、换片条件、对象动画与动作跳转","reason":"媒体开始方式与页面自动换片条件共同影响播放过程，不能把切换时间当作媒体时长。","chapter":5},{"id":"y2023q13","label":"排练计时会记录每张幻灯片的放映用时","reason":"用排练计时核对讲解和媒体节奏，但记录时长不等于录制全部旁白与内容。","chapter":5}],"topics":[]},"y2024q65":{"related":[{"id":"y2020q11","label":"幻灯片母版、版式与主题形成继承关系","reason":"编号与页脚的位置来自母版或版式，是否显示仍需在页眉和页脚中启用。","chapter":5},{"id":"y2020q12","label":"删除幻灯片要选中缩略图，隐藏不等于删除","reason":"标题页不显示编号只改编号外观，隐藏页面改变常规放映资格，两者都不同于删页。","chapter":5},{"id":"y2024q55","label":"在形状中放置光标后插入PAGE域","reason":"Word页码与PowerPoint编号都应使用动态字段，手输数字不会自动跟随页面变化。","chapter":3}],"topics":[]},"syllabus-ppt-output":{"related":[{"id":"y2023q45","label":"ppsx是PowerPoint放映文件扩展名","reason":"联系相邻知识理解作用范围","chapter":5},{"id":"y2024q46","label":"应用级选项与当前页视图","reason":"文件交付与应用默认选项分别在5.5和5.6查询。","chapter":5}],"topics":[]},"y2024q46":{"related":[{"id":"y2020q10","label":"浏览、普通、备注页和阅读视图的用途","reason":"先按编辑单页、管理顺序或观看放映的用途选择合适默认视图。","chapter":5},{"id":"y2023q45","label":"ppsx是PowerPoint放映文件扩展名","reason":"ppsx双击进入放映属于文件打开行为，不应与普通文稿的视图首选项混淆。","chapter":5}],"topics":[]}};
